    , m_nextWatcherId(1)
    , m_nextWebviewId(1)
    , m_nextTokenId(1)
    , m_totalAPICalls(0)
    , m_totalErrors(0)
{
}

VSCodeExtensionAPI::~VSCodeExtensionAPI() {
    if (m_initialized) {
        shutdown();
    }
}

VSCodeExtensionAPI& VSCodeExtensionAPI::instance() {
    static VSCodeExtensionAPI s_instance;
    return s_instance;
}

