    copyField(jsonGetString(json, "version"),        outManifest->version,      sizeof(outManifest->version));
    copyField(jsonGetString(json, "description"),    outManifest->description,  sizeof(outManifest->description));
    copyField(jsonGetString(json, "main"),           outManifest->main,         sizeof(outManifest->main));

