        }, "showInformationMessage", 1));

    // vscode.window.showWarningMessage
    JS_SetPropertyStr(cx, window, "showWarningMessage",
        JS_NewCFunction(cx, [](JSContext* c, JSValue this_val, int argc, JSValue* argv) -> JSValue {
