                        JS_Eval(extCtx, script.c_str(), script.size(),
                                "<event>", JS_EVAL_TYPE_GLOBAL);
                    }
                }
                break;
            }

            case JSMessage::Type::TimerFire: {
                // Timer callbacks are handled in the timer processing section
                break;
            }

            case JSMessage::Type::DisposeResource: {
                // Cleanup resources
                break;
            }

            default:
                break;
        }

