const char* VSCodeExtensionAPI::configGetString(const char* key, void* ctx) {
    auto* self = static_cast<VSCodeExtensionAPI*>(ctx);
    if (!self || !key) return "";
    
    // Route to Win32IDE settings via m_host
    if (self->m_host) {
        // Thread-local static buffer for returning strings from IDESettings
        // (caller must copy before next call)
        thread_local static std::string configBuffer;
        
        std::string k(key);
        
        // Map VS Code configuration keys to IDESettings fields
        if (k == "editor.fontFamily" || k == "fontName") {
            configBuffer = self->m_host->m_settings.fontName;
        } else if (k == "editor.fontSize" || k == "fontSize") {
            configBuffer = std::to_string(self->m_host->m_settings.fontSize);
        } else if (k == "editor.tabSize" || k == "tabSize") {
            configBuffer = std::to_string(self->m_host->m_settings.tabSize);
        } else if (k == "editor.wordWrap" || k == "wordWrap") {
            configBuffer = self->m_host->m_settings.wordWrapEnabled ? "on" : "off";
        } else if (k == "files.encoding" || k == "encoding") {
            configBuffer = self->m_host->m_settings.encoding;
        } else if (k == "files.eol" || k == "eolStyle") {
            configBuffer = self->m_host->m_settings.eolStyle;
        } else if (k == "ai.temperature" || k == "aiTemperature") {
            configBuffer = std::to_string(self->m_host->m_settings.aiTemperature);
        } else if (k == "ai.topP" || k == "aiTopP") {
            configBuffer = std::to_string(self->m_host->m_settings.aiTopP);
        } else if (k == "ai.maxTokens" || k == "aiMaxTokens") {
            configBuffer = std::to_string(self->m_host->m_settings.aiMaxTokens);
        } else if (k == "ai.contextWindow" || k == "aiContextWindow") {
            configBuffer = std::to_string(self->m_host->m_settings.aiContextWindow);
        } else if (k == "ai.modelPath" || k == "aiModelPath") {
            configBuffer = self->m_host->m_settings.aiModelPath;
        } else if (k == "ai.ollamaUrl" || k == "aiOllamaUrl") {
            configBuffer = self->m_host->m_settings.aiOllamaUrl;
        } else if (k == "workingDirectory") {
            configBuffer = self->m_host->m_settings.workingDirectory;
        } else {
            // Unknown key — return empty
            return "";
        }
        
        return configBuffer.c_str();
    }
    
    return "";
}

int VSCodeExtensionAPI::configGetInt(const char* key, int defaultVal, void* ctx) {
    auto* self = static_cast<VSCodeExtensionAPI*>(ctx);
    if (!self || !key || !self->m_host) return defaultVal;
    
    std::string k(key);
    if (k == "editor.fontSize" || k == "fontSize") return self->m_host->m_settings.fontSize;
    if (k == "editor.tabSize" || k == "tabSize") return self->m_host->m_settings.tabSize;
    if (k == "ai.maxTokens" || k == "aiMaxTokens") return self->m_host->m_settings.aiMaxTokens;
    if (k == "ai.contextWindow" || k == "aiContextWindow") return self->m_host->m_settings.aiContextWindow;
    if (k == "ai.topK" || k == "aiTopK") return self->m_host->m_settings.aiTopK;
    if (k == "files.autoSaveDelay" || k == "autoSaveIntervalSec") return self->m_host->m_settings.autoSaveIntervalSec;
    if (k == "server.port" || k == "localServerPort") return self->m_host->m_settings.localServerPort;
    if (k == "ai.failureMaxRetries" || k == "failureMaxRetries") return self->m_host->m_settings.failureMaxRetries;
    
    return defaultVal;
}

bool VSCodeExtensionAPI::configGetBool(const char* key, bool defaultVal, void* ctx) {
    auto* self = static_cast<VSCodeExtensionAPI*>(ctx);
    if (!self || !key || !self->m_host) return defaultVal;
    
    std::string k(key);
    if (k == "editor.lineNumbers" || k == "lineNumbersVisible") return self->m_host->m_settings.lineNumbersVisible;
    if (k == "editor.wordWrap" || k == "wordWrapEnabled") return self->m_host->m_settings.wordWrapEnabled;
    if (k == "files.autoSave" || k == "autoSaveEnabled") return self->m_host->m_settings.autoSaveEnabled;
    if (k == "editor.minimap.enabled" || k == "minimapEnabled") return self->m_host->m_settings.minimapEnabled;
    if (k == "editor.tabSpaces" || k == "useSpaces") return self->m_host->m_settings.useSpaces;
    if (k == "editor.syntaxColoring" || k == "syntaxColoringEnabled") return self->m_host->m_settings.syntaxColoringEnabled;
    if (k == "ai.ghostText" || k == "ghostTextEnabled") return self->m_host->m_settings.ghostTextEnabled;
    if (k == "ai.failureDetector" || k == "failureDetectorEnabled") return self->m_host->m_settings.failureDetectorEnabled;
    if (k == "server.enabled" || k == "localServerEnabled") return self->m_host->m_settings.localServerEnabled;
    
    return defaultVal;
}

